// Package transport provides predefined transport protocol.
package transport

// Protocol indicates the transport protocol.
type Protocol int

// Predefined transport protocols.
const (
	PurePayload Protocol = 0

	TTHeader Protocol = 1 << iota
	Framed
	HTTP
	GRPC
	HESSIAN2
	TTHeaderStreaming // value = 64, replaces old STREAMING constant
	GRPCStreaming     // value = 128

	TTHeaderFramed = TTHeader | Framed
)

// Deprecated: Use TTHeaderStreaming instead
const STREAMING = TTHeaderStreaming

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

// String prints human readable information.
func (tp Protocol) String() string {
	if tp == PurePayload {
		return "PurePayload"
	}

	// Define flags with their bit values in ascending order
	flags := []struct {
		bit  Protocol
		name string
	}{
		{TTHeader, "TTHeader"},
		{Framed, "Framed"},
		{HTTP, "HTTP"},
		{GRPC, "GRPC"},
		{HESSIAN2, "Hessian2"},
		{TTHeaderStreaming, "TTHeaderStreaming"},
		{GRPCStreaming, "GRPCStreaming"},
	}

	var parts []string
	for _, flag := range flags {
		if tp&flag.bit != 0 {
			parts = append(parts, flag.name)
		}
	}

	if len(parts) > 0 {
		result := parts[0]
		for i := 1; i < len(parts); i++ {
			result += "|" + parts[i]
		}
		return result
	}

	return Unknown
}
