{"path": "task/workspace/pkg/streaming/streaming.go", "start": 151, "lines": 153, "offset": 0, "total_lines": 303, "content": "// ClientStreamingClient provides typed client-streaming for client side
type ClientStreamingClient[Req, Res any] interface {
	ClientStream
	// Send sends a typed request
	Send(ctx context.Context, req *Req) error
	// CloseAndRecv closes send and receives the response
	CloseAndRecv(ctx context.Context) (*Res, error)
}

// clientStreamingClient implements ClientStreamingClient
type clientStreamingClient[Req, Res any] struct {
	ClientStream
}

// NewClientStreamingClient creates a typed client-streaming client
func NewClientStreamingClient[Req, Res any](st ClientStream) ClientStreamingClient[Req, Res] {
	return &clientStreamingClient[Req, Res]{ClientStream: st}
}

func (c *clientStreamingClient[Req, Res]) Send(ctx context.Context, req *Req) error {
	return c.ClientStream.SendMsg(ctx, req)
}

func (c *clientStreamingClient[Req, Res]) CloseAndRecv(ctx context.Context) (*Res, error) {
	if err := c.ClientStream.CloseSend(ctx); err != nil {
		return nil, err
	}
	m := new(Res)
	if err := c.ClientStream.RecvMsg(ctx, m); err != nil {
		return nil, err
	}
	return m, nil
}

// ClientStreamingServer provides typed client-streaming for server side
type ClientStreamingServer[Req, Res any] interface {
	ServerStream
	// Recv receives a typed request
	Recv(ctx context.Context) (*Req, error)
	// SendAndClose sends the response and closes
	SendAndClose(ctx context.Context, res *Res) error
}

// clientStreamingServer implements ClientStreamingServer
type clientStreamingServer[Req, Res any] struct {
	ServerStream
}

// NewClientStreamingServer creates a typed client-streaming server
func NewClientStreamingServer[Req, Res any](st ServerStream) ClientStreamingServer[Req, Res] {
	return &clientStreamingServer[Req, Res]{ServerStream: st}
}

func (c *clientStreamingServer[Req, Res]) Recv(ctx context.Context) (*Req, error) {
	m := new(Req)
	if err := c.ServerStream.RecvMsg(ctx, m); err != nil {
		return nil, err
	}
	return m, nil
}

func (c *clientStreamingServer[Req, Res]) SendAndClose(ctx context.Context, res *Res) error {
	return c.ServerStream.SendMsg(ctx, res)
}

// BidiStreamingClient provides typed bidirectional streaming for client side
type BidiStreamingClient[Req, Res any] interface {
	ClientStream
	// Send sends a typed request
	Send(ctx context.Context, req *Req) error
	// Recv receives a typed response
	Recv(ctx context.Context) (*Res, error)
}

// bidiStreamingClient implements BidiStreamingClient
type bidiStreamingClient[Req, Res any] struct {
	ClientStream
}

// NewBidiStreamingClient creates a typed bidirectional streaming client
func NewBidiStreamingClient[Req, Res any](st ClientStream) BidiStreamingClient[Req, Res] {
	return &bidiStreamingClient[Req, Res]{ClientStream: st}
}

func (b *bidiStreamingClient[Req, Res]) Send(ctx context.Context, req *Req) error {
	return b.ClientStream.SendMsg(ctx, req)
}

func (b *bidiStreamingClient[Req, Res]) Recv(ctx context.Context) (*Res, error) {
	m := new(Res)
	if err := b.ClientStream.RecvMsg(ctx, m); err != nil {
		return nil, err
	}
	return m, nil
}

// BidiStreamingServer provides typed bidirectional streaming for server side
type BidiStreamingServer[Req, Res any] interface {
	ServerStream
	// Recv receives a typed request
	Recv(ctx context.Context) (*Req, error)
	// Send sends a typed response
	Send(ctx context.Context, res *Res) error
}

// bidiStreamingServer implements BidiStreamingServer
type bidiStreamingServer[Req, Res any] struct {
	ServerStream
}

// NewBidiStreamingServer creates a typed bidirectional streaming server
func NewBidiStreamingServer[Req, Res any](st ServerStream) BidiStreamingServer[Req, Res] {
	return &bidiStreamingServer[Req, Res]{ServerStream: st}
}

func (b *bidiStreamingServer[Req, Res]) Recv(ctx context.Context) (*Req, error) {
	m := new(Req)
	if err := b.ServerStream.RecvMsg(ctx, m); err != nil {
		return nil, err
	}
	return m, nil
}

func (b *bidiStreamingServer[Req, Res]) Send(ctx context.Context, res *Res) error {
	return b.ServerStream.SendMsg(ctx, res)
}

// CloseCallbackRegister allows registering a callback when the stream closes
type CloseCallbackRegister interface {
	RegisterCloseCallback(cb func(error))
}

// GRPCStreamGetter provides access to the underlying gRPC stream
type GRPCStreamGetter interface {
	GetGRPCStream() Stream
}

// EventHandler handles stream events
type EventHandler func(ctx context.Context, evt stats.Event, err error)

// Args endpoint request
type Args struct {
	Stream       Stream
	ServerStream ServerStream
	ClientStream ClientStream
}

// Result endpoint response
type Result struct {
	Stream       Stream
	ServerStream ServerStream
	ClientStream ClientStream
}
